WITH ss AS (SELECT DISTINCT order_id, seller_id FROM order_items), s AS (SELECT sh.shipment_id, sh.order_id, sh.promised_date, CAST(sh.delivered_at_utc + INTERVAL 6 HOUR AS DATE) AS dd FROM shipments sh JOIN orders o ON o.order_id = sh.order_id WHERE sh.status = 'delivered' AND sh.delivered_at_utc IS NOT NULL AND NOT o.is_deleted) SELECT se.name, COUNT(DISTINCT s.shipment_id) AS n, AVG(CASE WHEN s.dd > s.promised_date THEN 1.0 ELSE 0.0 END) AS late_rate FROM s JOIN ss ON ss.order_id = s.order_id JOIN sellers se ON se.seller_id = ss.seller_id WHERE s.dd BETWEEN DATE '2026-07-01' AND DATE '2026-09-30' GROUP BY se.seller_id, se.name HAVING COUNT(DISTINCT s.shipment_id) >= 200 ORDER BY late_rate DESC LIMIT 1
